import{_ as e,b as t,f as r,I as i}from"./chunks/framework.DYvp_Vyw.js";const b=JSON.parse('{"title":"Matlab学习笔记008 - MMATLAB图形用户界面设计","description":"","frontmatter":{"title":"Matlab学习笔记008 - MMATLAB图形用户界面设计","date":"2025-05-07T01:46:14.000Z","tags":["数学建模","Matlab"],"head":[["meta",{"name":"descriptionx x x","content":"vitepress-theme-bluearchive Tags"}],["meta",{"name":"keywords","content":"vitepress theme bluearchive Tags"}]]},"headers":[],"relativePath":"posts/Matlab-Own-Study-008.md","filePath":"posts/Matlab-Own-Study-008.md"}'),o={name:"posts/Matlab-Own-Study-008.md"};function l(n,a,h,u,d,s){return r(),t("div",null,a[0]||(a[0]=[i(`<p>自己学习后整理的笔记（实时更新）</p><hr><blockquote><p>所谓图形用户界面是指由窗口、菜单、对话框等各种图形对象组成的用户界面。在这种用户界面下，用户的操作是通过“选择”各种图形对象来实现的。</p></blockquote><h1 id="一、图形窗口的控制" tabindex="-1">一、图形窗口的控制 <a class="header-anchor" href="#一、图形窗口的控制" aria-label="Permalink to &quot;一、图形窗口的控制&quot;">​</a></h1><h2 id="_1-建立图形窗口" tabindex="-1">1.建立图形窗口 <a class="header-anchor" href="#_1-建立图形窗口" aria-label="Permalink to &quot;1.建立图形窗口&quot;">​</a></h2><p>要建立一个图形窗口，有两种方法：</p><h3 id="_1-菜单操作" tabindex="-1">(1)菜单操作： <a class="header-anchor" href="#_1-菜单操作" aria-label="Permalink to &quot;(1)菜单操作：&quot;">​</a></h3><p>在MATLAB命令窗口选择File菜单中的New命令，再选取Figure子菜单，这样将建立一个标准的MATLAB图形窗口；</p><h3 id="_2-命令操作" tabindex="-1">(2)命令操作： <a class="header-anchor" href="#_2-命令操作" aria-label="Permalink to &quot;(2)命令操作：&quot;">​</a></h3><p>使用figure函数建立一个图形窗口，并返回该窗口的句柄。调用figure函数的一般格式为： 窗口句柄=figure(属性名1，属性值1，属性名2，属性值2，…) MATLAB通过对属性的操作来改变图形窗口的形式。</p><h2 id="_2-图形窗口的常用属性" tabindex="-1">2.图形窗口的常用属性 <a class="header-anchor" href="#_2-图形窗口的常用属性" aria-label="Permalink to &quot;2.图形窗口的常用属性&quot;">​</a></h2><h3 id="_1-menubar属性" tabindex="-1">(1) MenuBar属性 <a class="header-anchor" href="#_1-menubar属性" aria-label="Permalink to &quot;(1) MenuBar属性&quot;">​</a></h3><p>MenuBar属性的取值可以是figure(缺省值)或none。用来控制图形窗口是否应该具有菜单条。如果它的属性值为none，则表示该图形窗口没有菜单条。这时用户可以根据后面将介绍的uimenu()函数来加入自己的菜单条，如果属性值为figure，则该窗口将保持图形窗口默认的菜单条，这时也可以采用uimenu()函数在原默认的图形窗口菜单后面添加新的菜单项。</p><h3 id="_2-name属性" tabindex="-1">(2) Name属性 <a class="header-anchor" href="#_2-name属性" aria-label="Permalink to &quot;(2) Name属性&quot;">​</a></h3><p>Name属性的取值可以是任何字符串，它的缺省值为空。这个字符串作为图形窗口的标题。一般情况下，其标题形式为：Figure No.1:字符串。</p><h3 id="_3-numbertitle属性" tabindex="-1">(3) NumberTitle属性 <a class="header-anchor" href="#_3-numbertitle属性" aria-label="Permalink to &quot;(3) NumberTitle属性&quot;">​</a></h3><p>NumberTitle属性的取值是on(缺省值)或off。决定着在图形窗口的标题中是否以“Figure No.n:”为标题前缀，这里n是图形窗口的序号，即句柄值。</p><h1 id="_3-图形窗口控制函数" tabindex="-1">3.图形窗口控制函数 <a class="header-anchor" href="#_3-图形窗口控制函数" aria-label="Permalink to &quot;3.图形窗口控制函数&quot;">​</a></h1><h3 id="_1-设置图形窗口属性函数set" tabindex="-1">（1） 设置图形窗口属性函数set <a class="header-anchor" href="#_1-设置图形窗口属性函数set" aria-label="Permalink to &quot;（1） 设置图形窗口属性函数set&quot;">​</a></h3><p>set函数的调用格式为： set(窗口句柄，属性名1，属性值1，属性名2，属性值2，…)</p><h3 id="_2-获取句柄信息函数get" tabindex="-1">（2） 获取句柄信息函数get <a class="header-anchor" href="#_2-获取句柄信息函数get" aria-label="Permalink to &quot;（2） 获取句柄信息函数get&quot;">​</a></h3><p>调用格式为： V=get(句柄名，属性名) 其中V是返回的属性值。</p><h1 id="二、菜单设计" tabindex="-1">二、菜单设计 <a class="header-anchor" href="#二、菜单设计" aria-label="Permalink to &quot;二、菜单设计&quot;">​</a></h1><blockquote><p>MATLAB的各个图形窗口有自己的菜单栏，包括File、Edit、Windows和Help等菜单项。为了建立用户自己的菜单系统，可以先将图形窗口的MenuBar属性事先设置为none，以取消图形窗口缺省的菜单，然后再建立用户自己的菜单。</p></blockquote><h2 id="_1-建立用户菜单" tabindex="-1">1.建立用户菜单 <a class="header-anchor" href="#_1-建立用户菜单" aria-label="Permalink to &quot;1.建立用户菜单&quot;">​</a></h2><pre><code>要建立用户菜单可用uimenu函数，因其调用方法不同，该函数可以用于建立菜单条中的菜单项和子菜单中的菜单项。建立菜单条的函数调用形式为：
</code></pre><p>菜单项句柄=uimenu(图形窗口句柄，属性名1，属性值1，属性名2，属性值2，…) 建立子菜单的函数调用形式为： 子菜单句柄=uimenu(父菜单句柄，属性名1，属性值1，属性名2，属性值2，…)</p><h2 id="_2-菜单对象常用属性" tabindex="-1">2.菜单对象常用属性 <a class="header-anchor" href="#_2-菜单对象常用属性" aria-label="Permalink to &quot;2.菜单对象常用属性&quot;">​</a></h2><h3 id="_1-tag属性" tabindex="-1">（1） Tag属性 <a class="header-anchor" href="#_1-tag属性" aria-label="Permalink to &quot;（1） Tag属性&quot;">​</a></h3><p>Tag属性的取值是字符串，它定义了该菜单对象的一个标识值。定义了Tag属性后，在任何程序中都可以通过这个标识值找出该菜单对象。</p><h3 id="_2-type属性" tabindex="-1">（2） Type属性 <a class="header-anchor" href="#_2-type属性" aria-label="Permalink to &quot;（2） Type属性&quot;">​</a></h3><p>Type属的取值总是uimenu，这个属性值标明图形对象的类型。对菜单对象，其类型就是uimenu，用户不能改写这个属性。</p><h3 id="_3-userdata属性" tabindex="-1">（3） UserData属性 <a class="header-anchor" href="#_3-userdata属性" aria-label="Permalink to &quot;（3） UserData属性&quot;">​</a></h3><p>UserData属性的取值是一个矩阵，缺省值为空矩阵，用户可以在这个属性中保存与该菜单对象相关的重要数据或信息，借此可以达到传递数据或信息的目的。可以用set和get函数访问该属性。</p><h1 id="三、对话框设计" tabindex="-1">三、对话框设计 <a class="header-anchor" href="#三、对话框设计" aria-label="Permalink to &quot;三、对话框设计&quot;">​</a></h1><h2 id="_1-对话框的组成" tabindex="-1">1.对话框的组成 <a class="header-anchor" href="#_1-对话框的组成" aria-label="Permalink to &quot;1.对话框的组成&quot;">​</a></h2><ol><li>按钮(Push Button)</li><li>单选按钮(Radio Button)</li><li>复选框(Check Box)</li><li>列表框(List Box)</li><li>弹出式列表框(Popup List Box)</li><li>编辑框(Edit Box)</li><li>滑动条(Slider)</li><li>静态文本(Static Text)</li><li>边框(Frame)</li></ol><h2 id="_2-对话框的设计" tabindex="-1">2. 对话框的设计 <a class="header-anchor" href="#_2-对话框的设计" aria-label="Permalink to &quot;2. 对话框的设计&quot;">​</a></h2><h3 id="_1-建立控制对象" tabindex="-1">1). 建立控制对象 <a class="header-anchor" href="#_1-建立控制对象" aria-label="Permalink to &quot;1). 建立控制对象&quot;">​</a></h3><pre><code>MATLAB提供了用于建立控制对象的函数uicontrol，其调用格式为：
  对象句柄=uicontrol(窗口句柄，属性名1，属性值1，属性名2，属性值2，…)
</code></pre><h3 id="_2-控制对象的属性" tabindex="-1">2). 控制对象的属性 <a class="header-anchor" href="#_2-控制对象的属性" aria-label="Permalink to &quot;2). 控制对象的属性&quot;">​</a></h3><hr>`,42)]))}const p=e(o,[["render",l]]);export{b as __pageData,p as default};
